// Enumerate available ciphers and select one valid descriptor as output
const struct nettle_cipher * const *list = nettle_get_ciphers();
// Validate returned pointer and ensure null-terminated array with a sane upper bound
if (!list) { FUZZ_BAIL(); }
size_t count = 0;
for (const struct nettle_cipher * const *p = list; *p && count < 256; ++p) { ++count; }
if (count == 0 || count >= 256) { FUZZ_BAIL(); }
// Pick a random valid index within [0, count)
unsigned idx = (unsigned)(*FUZZ_PARAM(unsigned int) % count);
const struct nettle_cipher *desc = list[idx];
if (!desc) { FUZZ_BAIL(); }
// Basic invariants per API contract
FUZZ_ASSERT(desc->context_size > 0, "cipher context_size must be > 0");
// block_size is zero for stream ciphers; allow zero but track it
FUZZ_ASSERT(desc->key_size > 0, "cipher key_size must be > 0");
FUZZ_ASSERT(desc->set_encrypt_key && desc->set_decrypt_key, "cipher set_key fns must exist");
FUZZ_ASSERT(desc->encrypt && desc->decrypt, "cipher crypt fns must exist");
// Define output object and annotate with attributes for downstream stubs
struct nettle_cipher *cipher = (struct nettle_cipher *) desc; // cast away const for fuzzer bookkeeping only; do not modify contents
FUZZ_SET_ATTR_STR(cipher, "name", desc->name ? desc->name : "");
FUZZ_SET_ATTR_INT(cipher, "context_size", (int) desc->context_size);
FUZZ_SET_ATTR_INT(cipher, "block_size", (int) desc->block_size);
FUZZ_SET_ATTR_INT(cipher, "key_size", (int) desc->key_size);
