import os
import random
from typing import List

# Data type: raw key bytes
# Many stubs expect specific key lengths (AES 16/24/32; XTS 32/64; RC4 1..256; Blowfish 8..56;
# Serpent 16..32; Twofish 16/24/32; DES 8; 3DES 24; Camellia 16/24/32; Poly1305-AES 32; Salsa20 16/32; bcrypt salts 16).
# Strategy: choose a target family and emit a buffer that is immediately useful for FUZZ_PARAM_STR
# and FUZZ_PARAM(uint8_t[N]) consumers. We compose the buffer as concatenation of segments so that
# the first segment often satisfies fixed-size requests directly, while additional bytes serve
# secondary FUZZ_PARAM_STR calls in the same stub.

FIXED_SIZES = [
    16,   # AES-128, Camellia-128, SM4, CFB IV, CBC IV, bcrypt salt, Salsa20 key (128)
    24,   # AES-192, Camellia-192, Twofish-192, Serpent 192
    32,   # AES-256, Camellia-256, Twofish-256, Serpent 256, Poly1305-AES key
    8,    # DES key, NIST keywrap IV, 3DES block size
    5,    # ARCTWO40
    8,    # ARCTWO64 (duplicate tolerated)
    16,   # ARCTWO128
    24,   # 3DES key
    32,   # XTS-AES128 total (two 16s)
    64,   # XTS-AES256 total (two 32s)
]

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Mix printable and full-range bytes for broader coverage
    out = bytearray(n)
    for i in range(n):
        if rng.random() < 0.7:
            out[i] = rng.randrange(0, 256)
        else:
            # bias towards ASCII for string uses
            out[i] = rng.choice(list(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/=\n\r\t\x00"))
    return bytes(out)

def _mk_xts_pair(rng: random.Random, bits: int) -> bytes:
    if bits == 128:
        k1 = _rand_bytes(rng, 16)
        k2 = _rand_bytes(rng, 16)
        return k1 + k2
    else:
        k1 = _rand_bytes(rng, 32)
        k2 = _rand_bytes(rng, 32)
        return k1 + k2

def _mk_rc4_key(rng: random.Random) -> bytes:
    klen = rng.randrange(1, 257)
    return _rand_bytes(rng, klen)

def _mk_blowfish_key(rng: random.Random) -> bytes:
    klen = rng.randrange(8, 57)  # 8..56
    return _rand_bytes(rng, klen)

def _mk_serpent_key(rng: random.Random) -> bytes:
    klen = rng.randrange(16, 33)
    return _rand_bytes(rng, klen)

def _mk_twofish_key(rng: random.Random) -> bytes:
    klen = rng.choice([16, 24, 32])
    return _rand_bytes(rng, klen)

def _mk_salsa20_key(rng: random.Random) -> bytes:
    return _rand_bytes(rng, rng.choice([16, 32]))

def _mk_pbkdf_material(rng: random.Random) -> bytes:
    # Provide key and salt concatenated with a delimiter region so multiple FUZZ_PARAM_STR calls have data
    key = _rand_bytes(rng, rng.randrange(0, 65))
    salt = _rand_bytes(rng, rng.randrange(0, 65))
    return key + b"\x00\x00" + salt

def _mk_aes_family(rng: random.Random) -> bytes:
    # Choose 128/192/256
    bits = rng.choice([128, 192, 256])
    size = bits // 8
    key = _rand_bytes(rng, size)
    # Append an IV-sized region (16) and some plaintext to satisfy stubs that need more FUZZ_PARAM_STR
    iv = _rand_bytes(rng, 16)
    pt_len = rng.randrange(16, 16*8+1, 16)  # multiples of block size up to 128 bytes
    pt = _rand_bytes(rng, pt_len)
    return key + iv + pt

def _mk_camellia_family(rng: random.Random) -> bytes:
    size = rng.choice([16, 24, 32])
    return _rand_bytes(rng, size) + _rand_bytes(rng, 16)

def _mk_gcm_key(rng: random.Random) -> bytes:
    # 16/24/32 for AES-GCM, plus a 12 or 16-byte IV region
    size = rng.choice([16, 24, 32])
    iv = _rand_bytes(rng, rng.choice([12, 16]))
    return _rand_bytes(rng, size) + iv

def _mk_bcrypt_material(rng: random.Random) -> bytes:
    # key (<=72), scheme (2-4 ascii), salt 16
    key = _rand_bytes(rng, rng.randrange(1, 73))
    scheme = _rand_bytes(rng, rng.randrange(2, 5))
    salt = _rand_bytes(rng, 16)
    return key + scheme + salt

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.randrange(0, 14)
    if choice == 0:
        buf = _mk_aes_family(rng)
    elif choice == 1:
        buf = _mk_camellia_family(rng)
    elif choice == 2:
        buf = _mk_gcm_key(rng)
    elif choice == 3:
        buf = _mk_rc4_key(rng)
    elif choice == 4:
        buf = _mk_blowfish_key(rng)
    elif choice == 5:
        buf = _mk_serpent_key(rng)
    elif choice == 6:
        buf = _mk_twofish_key(rng)
    elif choice == 7:
        buf = _mk_salsa20_key(rng)
    elif choice == 8:
        buf = _mk_xts_pair(rng, 128)
    elif choice == 9:
        buf = _mk_xts_pair(rng, 256)
    elif choice == 10:
        # DES/3DES sequence: provide 24 with leading 8 too
        des = _rand_bytes(rng, 8)
        des3 = _rand_bytes(rng, 24)
        buf = des + des3
    elif choice == 11:
        # ARCTWO variants 5/8/16 and generic 1..128
        var = rng.choice([5, 8, 16, rng.randrange(1, 129)])
        buf = _rand_bytes(rng, var)
    elif choice == 12:
        buf = _mk_bcrypt_material(rng)
    else:
        buf = _mk_pbkdf_material(rng)

    # Ensure the buffer is non-empty and <= 4096 bytes, and append a small trailer so
    # subsequent FUZZ_PARAM_STR calls have data.
    if not buf:
        buf = _rand_bytes(rng, 16)
    trailer = _rand_bytes(rng, rng.randrange(0, 65))
    out = buf + trailer
    if len(out) > 4096:
        out = out[:4096]
    return out

import random
from typing import List

# This generator produces valid DER for PKCS#1 RSAPublicKey and RSAPrivateKey.
# It uses small primes and ensures e is coprime with phi to avoid failures.

# ASN.1 helpers

def der_len(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    out = []
    while n > 0:
        out.append(n & 0xFF)
        n >>= 8
    out.reverse()
    return bytes([0x80 | len(out)]) + bytes(out)

def der_integer(n: int) -> bytes:
    # Encode non-negative INTEGER
    if n == 0:
        content = b"\x00"
    else:
        out = []
        x = n
        while x > 0:
            out.append(x & 0xFF)
            x >>= 8
        out.reverse()
        content = bytes(out)
        if content[0] & 0x80:
            content = b"\x00" + content
    return b"\x02" + der_len(len(content)) + content

def der_sequence(components: List[bytes]) -> bytes:
    content = b"".join(components)
    return b"\x30" + der_len(len(content)) + content

# Math helpers

def egcd(a, b):
    while b != 0:
        a, b = b, a % b
    # When loop exits, a = gcd
    return a

# PKCS#1 builders

def build_public_der(n: int, e: int) -> bytes:
    return der_sequence([der_integer(n), der_integer(e)])

def modinv_safe(a: int, m: int) -> int:
    # Compute modular inverse using extended Euclid; returns 0 if none exists
    t, new_t = 0, 1
    r, new_r = m, a % m
    while new_r != 0:
        q = r // new_r
        t, new_t = new_t, t - q * new_t
        r, new_r = new_r, r - q * new_r
    if r != 1:
        return 0
    if t < 0:
        t += m
    return t

def build_private_der(p: int, q: int, e: int) -> bytes:
    if p < q:
        p, q = q, p
    n = p * q
    phi = (p - 1) * (q - 1)
    # Ensure e and phi are coprime; if not, adjust e upward to nearest coprime odd
    ee = e
    if ee <= 1:
        ee = 3
    if ee % 2 == 0:
        ee += 1
    while egcd(ee, phi) != 1:
        ee += 2
    d = modinv_safe(ee, phi)
    if d == 0:
        # As a last resort pick a fixed good exponent relative to phi by search
        ee = 3
        while egcd(ee, phi) != 1:
            ee += 2
        d = modinv_safe(ee, phi)
    dP = d % (p - 1)
    dQ = d % (q - 1)
    qInv = modinv_safe(q, p)
    # qInv must exist since p,q are primes and distinct
    components = [
        der_integer(0),
        der_integer(n),
        der_integer(ee),
        der_integer(d),
        der_integer(p),
        der_integer(q),
        der_integer(dP),
        der_integer(dQ),
        der_integer(qInv),
    ]
    return der_sequence(components)

# Small primes buckets
SMALL_PRIMES_16 = [
    257, 263, 269, 271, 277, 281, 283, 293, 307, 311, 313, 317, 331, 337,
]
SMALL_PRIMES_24 = [
    4099, 4127, 4133, 4153, 4177, 4211, 4229, 4253, 4273, 4289, 4337, 4363,
]
SMALL_PRIMES_32 = [
    12289, 12323, 12347, 12373, 12391, 12413, 12421, 12433, 12437, 12451,
]
PUBLIC_EXPONENTS = [3, 5, 17, 257, 65537]

def pick_primes(rng: random.Random):
    bucket = rng.choice([SMALL_PRIMES_16, SMALL_PRIMES_24, SMALL_PRIMES_32])
    p = rng.choice(bucket)
    q = rng.choice(bucket)
    while q == p:
        q = rng.choice(bucket)
    return p, q

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.choice(["public", "private", "public_big"])

    if mode == "public" or mode == "public_big":
        p, q = pick_primes(rng)
        n = p * q
        e = rng.choice(PUBLIC_EXPONENTS)
        # Ensure gcd(e, phi) == 1 so that follow-on prepare steps are likely to succeed
        phi = (p - 1) * (q - 1)
        # If not coprime, pick a small odd exponent that is
        ee = e
        if egcd(ee, phi) != 1:
            ee = 3
            while egcd(ee, phi) != 1:
                ee += 2
        # Optionally enlarge modulus slightly to vary size while keeping e valid for parsing
        if mode == "public_big" and rng.random() < 0.4:
            r = rng.choice(SMALL_PRIMES_16 + SMALL_PRIMES_24)
            n = n * r
        return build_public_der(n, ee)

    # private
    # Mix sizes to vary n length
    if rng.random() < 0.5:
        p = rng.choice(SMALL_PRIMES_32)
        q = rng.choice(SMALL_PRIMES_24 + SMALL_PRIMES_16)
        if q == p:
            q = q + 2 if q % 2 else q + 1
    else:
        p, q = pick_primes(rng)
    e = rng.choice(PUBLIC_EXPONENTS)
    return build_private_der(p, q, e)
